1	package netdiag
2	
3	import (
4		"errors"
5		"net/netip"
6		"slices"
7		"strings"
8		"testing"
9	
10		"github.com/charmbracelet/x/ansi"
11	
12		"github.com/anthnel/devdesk/internal/docker"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	func prioOf(n int) *int { return &n }
17	
18	// ep builds an endpoint; gw and ip may be empty (no address).
19	func ep(name, ip, gw string, prio *int) docker.EndpointNetwork {
20		e := docker.EndpointNetwork{Name: name, GwPriority: prio}
21		if ip != "" {
22			e.IPv4 = netip.MustParseAddr(ip)
23		}
24		if gw != "" {
25			e.Gateway = netip.MustParseAddr(gw)
26		}
27		return e
28	}
29	
30	func TestPathContainerDefaultRouteNetwork(t *testing.T) {
31		a0 := ep("a", "172.18.0.5", "172.18.0.1", prioOf(0))
32		b10 := ep("b", "172.19.0.5", "172.19.0.1", prioOf(10))
33		tests := []struct {
34			name   string
35			nets   []docker.EndpointNetwork
36			want   string // "" means not found
37			wantOK bool
38		}{
39			{"one endpoint with a gateway", []docker.EndpointNetwork{a0}, "a", true},
40			{"one endpoint with a gateway and no priority",
41				[]docker.EndpointNetwork{ep("a", "172.18.0.5", "172.18.0.1", nil)}, "a", true},
42			{"an internal network cannot hold the default route",
43				[]docker.EndpointNetwork{a0, ep("b", "10.0.0.2", "", prioOf(50))}, "a", true},
44			{"the strictly highest priority wins", []docker.EndpointNetwork{a0, b10}, "b", true},
45			{"the strictly highest priority wins whatever the order", []docker.EndpointNetwork{b10, a0}, "b", true},
46			{"a tie is never guessed (H8)", []docker.EndpointNetwork{
47				ep("a", "172.18.0.5", "172.18.0.1", prioOf(5)),
48				ep("b", "172.19.0.5", "172.19.0.1", prioOf(5)),
49			}, "", false},
50			{"a tie at the top is never guessed", []docker.EndpointNetwork{
51				ep("a", "172.18.0.5", "172.18.0.1", prioOf(1)),
52				ep("b", "172.19.0.5", "172.19.0.1", prioOf(7)),
53				ep("c", "172.20.0.5", "172.20.0.1", prioOf(7)),
54			}, "", false},
55			{"a priority missing on one candidate is never guessed", []docker.EndpointNetwork{
56				ep("a", "172.18.0.5", "172.18.0.1", nil),
57				ep("b", "172.19.0.5", "172.19.0.1", prioOf(3)),
58			}, "", false},
59			{"no priority on any candidate is never guessed", []docker.EndpointNetwork{
60				ep("a", "172.18.0.5", "172.18.0.1", nil),
61				ep("b", "172.19.0.5", "172.19.0.1", nil),
62			}, "", false},
63			{"no gateway anywhere", []docker.EndpointNetwork{
64				ep("a", "172.18.0.5", "", prioOf(0)),
65				ep("b", "172.19.0.5", "", prioOf(1)),
66			}, "", false},
67			{"no endpoint", nil, "", false},
68		}
69		for _, tt := range tests {
70			t.Run(tt.name, func(t *testing.T) {
71				before := slices.Clone(tt.nets)
72				got, ok := defaultRouteNetwork(tt.nets)
73				if ok != tt.wantOK || got.Name != tt.want {
74					t.Fatalf("defaultRouteNetwork = (%q, %v), want (%q, %v)", got.Name, ok, tt.want, tt.wantOK)
75				}
76				if !slices.EqualFunc(tt.nets, before, func(x, y docker.EndpointNetwork) bool {
77					return x.Name == y.Name && x.IPv4 == y.IPv4 && x.Gateway == y.Gateway
78				}) {
79					t.Errorf("defaultRouteNetwork modified its input")
80				}
81			})
82		}
83	}
84	
85	func TestPathContainerNew(t *testing.T) {
86		src := pathSource{ID: "abc123", Name: "web-1", Image: "nginx"}
87		app := ep("app_net", "172.18.0.5", "172.18.0.1", prioOf(0))
88		tests := []struct {
89			name        string
90			n           docker.ContainerNetworking
91			err         error
92			attach      containerAttach
93			known       bool
94			wantCont    string
95			wantNetwork string
96			wantTrace   string
97		}{
98			{
99				name: "inspection failed", err: errors.New("boom"),
100				attach: attachUndetermined, known: false,
101				wantCont: "web-1", wantNetwork: "undetermined",
102				wantTrace: "from this machine, not from the container",
103			},
104			{
105				name:   "one network",
106				n:      docker.ContainerNetworking{Name: "web-1", Running: true, Mode: "app_net", Networks: []docker.EndpointNetwork{app}},
107				attach: attachNetwork, known: true,
108				wantCont: "web-1 (172.18.0.5)", wantNetwork: "app_net via 172.18.0.1",
109				wantTrace: "from this machine, not from the container",
110			},
111			{
112				name:   "default bridge",
113				n:      docker.ContainerNetworking{Name: "web-1", Running: true, Mode: "bridge", Networks: []docker.EndpointNetwork{ep("bridge", "172.17.0.3", "172.17.0.1", prioOf(0))}},
114				attach: attachNetwork, known: true,
115				wantCont: "web-1 (172.17.0.3)", wantNetwork: "bridge via 172.17.0.1",
116				wantTrace: "from this machine, not from the container",
117			},
118			{
119				name:   "not running",
120				n:      docker.ContainerNetworking{Name: "web-1", Running: false, Mode: "app_net", Networks: []docker.EndpointNetwork{app}},
121				attach: attachUndetermined, known: true,
122				wantCont: "web-1 (not running)", wantNetwork: "undetermined",
123				wantTrace: "from this machine, not from the container",
124			},
125			{
126				name: "two networks, higher priority wins",
127				n: docker.ContainerNetworking{Name: "web-1", Running: true, Mode: "app_net", Networks: []docker.EndpointNetwork{
128					ep("a", "172.18.0.5", "172.18.0.1", prioOf(0)),
129					ep("b", "172.19.0.5", "172.19.0.1", prioOf(10)),
130				}},
131				attach: attachNetwork, known: true,
132				wantCont: "web-1 (172.19.0.5)", wantNetwork: "b via 172.19.0.1",
133				wantTrace: "from this machine, not from the container",
134			},
135			{
136				name: "two networks, a tie is undetermined",
137				n: docker.ContainerNetworking{Name: "web-1", Running: true, Mode: "a", Networks: []docker.EndpointNetwork{
138					ep("a", "172.18.0.5", "172.18.0.1", prioOf(0)),
139					ep("b", "172.19.0.5", "172.19.0.1", prioOf(0)),
140				}},
141				attach: attachUndetermined, known: true,
142				wantCont: "web-1", wantNetwork: "undetermined (2 networks)",
143				wantTrace: "from this machine, not from the container",
144			},
145			{
146				name: "host mode",
147				n: docker.ContainerNetworking{Name: "web-1", Running: true, Mode: "host",
148					Networks: []docker.EndpointNetwork{ep("host", "", "", nil)}},
149				attach: attachHost, known: true,
150				wantCont: "web-1", wantNetwork: "host (shares this machine's stack)",
151				wantTrace: "from this machine (shared with the container)",
152			},
153		}
154		for _, tt := range tests {
155			t.Run(tt.name, func(t *testing.T) {
156				got := newPathContainer(src, tt.n, tt.err)
157				if got.Known != tt.known || got.Attach != tt.attach {
158					t.Fatalf("Known/Attach = %v/%v, want %v/%v", got.Known, got.Attach, tt.known, tt.attach)
159				}
160				if got.containerText() != tt.wantCont {
161					t.Errorf("containerText = %q, want %q", got.containerText(), tt.wantCont)
162				}
163				if got.networkText() != tt.wantNetwork {
164					t.Errorf("networkText = %q, want %q", got.networkText(), tt.wantNetwork)
165				}
166				if got.traceText() != tt.wantTrace {
167					t.Errorf("traceText = %q, want %q", got.traceText(), tt.wantTrace)
168				}
169			})
170		}
171	}
172	
173	// Modes the plan leaves without a fixed sentence: only the attachment, the
174	// absence of a bridge line and the plain text are pinned.
175	func TestPathContainerNewOtherModes(t *testing.T) {
176		src := pathSource{ID: "abc123", Name: "web-1"}
177		tests := []struct {
178			name   string
179			mode   string
180			attach containerAttach
181		}{
182			{"none", "none", attachNone},
183			{"shared with another container", "container:abc", attachShared},
184		}
185		for _, tt := range tests {
186			t.Run(tt.name, func(t *testing.T) {
187				got := newPathContainer(src, docker.ContainerNetworking{Name: "web-1", Running: true, Mode: tt.mode}, nil)
188				if got.Attach != tt.attach {
189					t.Fatalf("Attach = %v, want %v", got.Attach, tt.attach)
190				}
191				if got.networkText() == "" || strings.Contains(got.networkText(), " via ") {
192					t.Errorf("networkText = %q, want a sentence with no gateway", got.networkText())
193				}
194			})
195		}
196	}
197	
198	// H12: the engine's own text reaches the cells already sanitized.
199	func TestPathContainerNewSanitizesEngineText(t *testing.T) {
200		src := pathSource{ID: "abc123", Name: "web-1"}
201		n := docker.ContainerNetworking{
202			Name: "we\x1b[31mb-1‮", Running: true, Mode: "evil\x1b]0;pwn\a",
203			Networks: []docker.EndpointNetwork{ep("ev\x1b[1mil​_net", "172.18.0.5", "172.18.0.1", prioOf(0))},
204		}
205		got := newPathContainer(src, n, nil)
206		for _, c := range []string{got.containerText(), got.networkText(), got.traceText()} {
207			if ansi.Strip(c) != c || strings.ContainsAny(c, "\x1b\a‮​") {
208				t.Errorf("cell %q is not display-safe", c)
209			}
210		}
211		if got.networkText() != "evil_net via 172.18.0.1" {
212			t.Errorf("networkText = %q, want %q", got.networkText(), "evil_net via 172.18.0.1")
213		}
214	}
215	
216	func TestPathContainerNewDoesNotMutateItsInput(t *testing.T) {
217		nets := []docker.EndpointNetwork{
218			ep("b", "172.19.0.5", "172.19.0.1", prioOf(1)),
219			ep("a", "172.18.0.5", "172.18.0.1", prioOf(0)),
220		}
221		n := docker.ContainerNetworking{Name: "web-1", Running: true, Mode: "a", Networks: nets}
222		_ = newPathContainer(pathSource{ID: "abc123", Name: "web-1"}, n, nil)
223		if nets[0].Name != "b" || nets[1].Name != "a" || n.Name != "web-1" || len(n.Networks) != 2 {
224			t.Errorf("newPathContainer modified its input: %+v", n)
225		}
226	}
227	
228	// Dim rows: undetermined, none and the trace row; the others take the default colour.
229	func TestPathColumnContainerRowStyles(t *testing.T) {
230		src := pathSource{ID: "abc123", Name: "web-1"}
231		app := ep("app_net", "172.18.0.5", "172.18.0.1", prioOf(0))
232		ok := newPathContainer(src, docker.ContainerNetworking{Name: "web-1", Running: true, Mode: "app_net", Networks: []docker.EndpointNetwork{app}}, nil)
233		bad := newPathContainer(src, docker.ContainerNetworking{}, errors.New("boom"))
234		tests := []struct {
235			name string
236			step pathStep
237			dim  bool
238		}{
