1	package netdiag
2	
3	import (
4		"fmt"
5		"net"
6		"net/netip"
7		"strconv"
8		"time"
9	
10		"github.com/anthnel/devdesk/internal/netcheck"
11		"github.com/anthnel/devdesk/internal/nettrace"
12	)
13	
14	// pathStepKind says which kind of row a pathStep is.
15	type pathStepKind int
16	
17	// The kinds of row, in the order the column shows them.
18	const (
19		stepContainer pathStepKind = iota
20		stepNetwork
21		stepSource
22		stepInterface
23		stepGateway
24		stepTrace
25		stepHop
26	)
27	
28	// pathRoute is the way out of this machine for the traced address.
29	type pathRoute struct {
30		Known     bool // false: the lookup failed; interface and gateway are undetermined
31		Interface string
32		Source    netip.Addr // invalid: the stack did not say
33		Gateway   netip.Addr // invalid: directly connected
34	}
35	
36	// pathStep is one row of the Path column.
37	type pathStep struct {
38		Kind      pathStepKind
39		Container pathContainer // stepContainer, stepNetwork, stepTrace
40		Route     pathRoute     // stepInterface, stepGateway
41		Hop       nettrace.Hop  // stepHop
42	}
43	
44	const (
45		sourceLabel       = "this machine"
46		routeUndetermined = "undetermined"
47		gatewayDirect     = "directly connected"
48	)
49	
50	// newPathRoute converts a route lookup into a pathRoute. A failed lookup
51	// discards whatever the hop holds. Addresses are unmapped to IPv4 when they can be.
52	func newPathRoute(hop netcheck.RouteHop, err error) pathRoute {
53		if err != nil {
54			return pathRoute{}
55		}
56		return pathRoute{
57			Known:     true,
58			Interface: hop.Interface,
59			Source:    addrFromIP(hop.Source),
60			Gateway:   addrFromIP(hop.Gateway),
61		}
62	}
63	
64	// addrFromIP returns ip as an unmapped netip.Addr, or the zero Addr for a nil or invalid ip.
65	func addrFromIP(ip net.IP) netip.Addr {
66		addr, ok := netip.AddrFromSlice(ip)
67		if !ok {
68			return netip.Addr{}
69		}
70		return addr.Unmap()
71	}
72	
73	// pathSteps returns the rows of the Path column: the source, then the
74	// interface and gateway when route is not nil, then the hops as selected by
75	// visiblePathHops. It returns nil while neither a route nor a hop exists.
76	// Neither input is modified.
77	func pathSteps(_ *pathContainer, route *pathRoute, hops []nettrace.Hop) []pathStep {
78		if route == nil && len(hops) == 0 {
79			return nil
80		}
81		steps := []pathStep{{Kind: stepSource}}
82		if route != nil {
83			steps = append(steps,
84				pathStep{Kind: stepInterface, Route: *route},
85				pathStep{Kind: stepGateway, Route: *route},
86			)
87		}
88		for _, h := range visiblePathHops(hops) {
89			steps = append(steps, pathStep{Kind: stepHop, Hop: h})
90		}
91		return steps
92	}
93	
94	// hopCell is the TTL of a hop row; empty for the local rows.
95	func (s pathStep) hopCell() string {
96		if s.Kind != stepHop {
97			return ""
98		}
99		return strconv.Itoa(s.Hop.TTL)
100	}
101	
102	// stepCell names the kind of row.
103	func (s pathStep) stepCell() string {
104		switch s.Kind {
105		case stepSource:
106			return "source"
107		case stepInterface:
108			return "interface"
109		case stepGateway:
110			return "gateway"
111		}
112		return s.Hop.Kind.String()
113	}
114	
115	// addressCell is the main text of the row.
116	func (s pathStep) addressCell() string {
117		switch s.Kind {
118		case stepSource:
119			return sourceLabel
120		case stepInterface:
121			return s.Route.interfaceText()
122		case stepGateway:
123			return s.Route.gatewayText()
124		}
125		return addrOrDash(s.Hop.Addr)
126	}
127	
128	// rttCell is the round-trip time of a hop that answered; "-" otherwise.
129	func (s pathStep) rttCell() string {
130		if s.Kind != stepHop {
131			return ""
132		}
133		if s.Hop.RTT <= 0 {
134			return "-"
135		}
136		return fmt.Sprintf("%.1f ms", float64(s.Hop.RTT)/float64(time.Millisecond))
137	}
138	
139	// interfaceText is the interface name, followed by the source address when known.
140	func (r pathRoute) interfaceText() string {
141		if !r.Known || (r.Interface == "" && !r.Source.IsValid()) {
142			return routeUndetermined
143		}
144		name := r.Interface
145		if name == "" {
146			name = "unnamed"
147		}
148		if !r.Source.IsValid() {
149			return name
150		}
151		return name + " (" + r.Source.String() + ")"
152	}
153	
154	// gatewayText is the gateway address, or says the destination is directly connected.
155	func (r pathRoute) gatewayText() string {
156		switch {
157		case !r.Known:
158			return routeUndetermined
159		case !r.Gateway.IsValid() || r.Gateway.IsUnspecified():
160			return gatewayDirect
161		}
162		return r.Gateway.String()
163	}
164	
165	// addrOrDash formats an address, or "-" when there is none.
166	func addrOrDash(a netip.Addr) string {
167		if !a.IsValid() {
168			return "-"
169		}
170		return a.String()
171	}
