func TestPathStepsContainerSourceStaysThisMachine(t *testing.T) {
	steps := pathSteps(stepsContainer(t, "app_net"), stepsRoute, []nettrace.Hop{stepsHop1, stepsHop3})
	var sources []pathStep
	for _, s := range steps {
